":2},{"id":"card-388","pack":"Digital Pack","title":"Room inspection!","text":"The person with the messiest room must drink","minPlayers":2},{"id":"card-389","pack":"Digital Pack","title":"Ghoul","text":"Anyone sitting in the dark must drink","minPlayers":2}]$cards$::jsonb;
