create or replace function reparty_private.game_action(p_action text, p_room text, p_data jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $game$
declare
  u uuid := auth.uid(); r public.reparty_rooms%rowtype; g jsonb; pb jsonb; snap jsonb;
  roster jsonb; chosen jsonb; catalog jsonb; deck jsonb; card jsonb; current_card jsonb; effects jsonb;
  who jsonb; others jsonb; names jsonb; item jsonb; txt text; key text; value text;
  total integer; idx integer; turn_no integer; duration integer; seconds integer; next_rev integer;
  stamp timestamptz := clock_timestamp();
begin
  if u is null then raise exception 'Sign in to play.'; end if;
  if p_data is null or jsonb_typeof(p_data) <> 'object' then raise exception 'Invalid game request.'; end if;
  -- Use the existing auth, membership, presence and locking path, in the same lock order.
  snap := public.reparty_action('snapshot', p_room, '{}'::jsonb);
  select * into r from public.reparty_rooms where id=p_room for update;
  g := coalesce(r.settings->'game', '{"mode":"watch","revision":0}'::jsonb);
  pb := r.playback;
  if coalesce((p_data->>'revision')::integer,-1) <> coalesce((g->>'revision')::integer,0) then
    return snap || '{"game_stale":true}'::jsonb;
  end if;
  next_rev := coalesce((g->>'revision')::integer,0)+1;
  if p_action='enter' and coalesce(g->>'mode','watch')='watch' then
    g := g || jsonb_build_object('mode','game','host',u);
  elsif p_action='takeover' then
    if exists(select 1 from public.reparty_members where room_id=p_room and user_id=(g->>'host')::uuid and last_seen>stamp-interval '60 seconds') then
      raise exception 'The game host is still here.';
    end if;
    g := g || jsonb_build_object('host',u);
  else
    if g->>'host' is distinct from u::text then raise exception 'Only the game host can do that.'; end if;
    if g->>'mode' is distinct from 'game' then raise exception 'Switch to Game mode first.'; end if;
    if p_action='exit' then
      g := g || '{"mode":"watch","timer_end":null}'::jsonb;
    elsif p_action='reset' then
      g := jsonb_build_object('mode','game','host',u);
    elsif p_action='start' then
      if jsonb_typeof(p_data->'players') is distinct from 'array' or jsonb_array_length(p_data->'players') not between 2 and 24 then raise exception 'Add between 2 and 24 players.'; end if;
      roster := '[]'::jsonb;
      for item in select * from jsonb_array_elements(p_data->'players') loop
        if char_length(trim(coalesce(item->>'name',''))) not between 1 and 32 then raise exception 'Player names must be 1–32 characters.'; end if;
        if exists(select 1 from jsonb_array_elements(roster) v where lower(v->>'name')=lower(trim(item->>'name'))) then raise exception 'Use different player names.'; end if;
        if coalesce((item->>'avatar_id')::integer,-1) not between 0 and 99 then raise exception 'Choose a valid avatar.'; end if;
        roster := roster || jsonb_build_array(jsonb_build_object('name',trim(item->>'name'),'avatar_id',(item->>'avatar_id')::integer));
      end loop;
      if jsonb_typeof(p_data->'packs') is distinct from 'array' then raise exception 'Choose a pack.'; end if;
      chosen := p_data->'packs';
      duration := (p_data->>'turns')::integer; seconds := (p_data->>'seconds')::integer;
      if duration is null or duration not between 1 and 10 or seconds is null or seconds not in (10,20,30,60) then raise exception 'Choose a valid rule duration and timer.'; end if;
      select jsonb_agg(v order by random()) into deck from jsonb_array_elements(reparty_private.card_catalog()) v
        where chosen ? (v->>'pack') and (v->>'minPlayers')::integer<=jsonb_array_length(roster);
      if deck is null then raise exception 'Choose at least one pack.'; end if;
      g := jsonb_build_object('mode','game','host',u,'players',roster,'packs',chosen,'deck',deck,'turns',duration,'seconds',seconds,'round',0,'rules','[]'::jsonb,'history','[]'::jsonb);
    elsif p_action in ('next','skip') then
      if g->'deck' is null then raise exception 'Start the game first.'; end if;
    elsif p_action='wheel' then
      if g->'players' is null then raise exception 'Start the game first.'; end if;
      select v into who from jsonb_array_elements(g->'players') v order by random() limit 1;
      g := g || jsonb_build_object('wheel',who->>'name');
    elsif p_action='timer' then
      if not coalesce((g->'current'->>'timed')::boolean,false) then raise exception 'This card has no timer.'; end if;
      if g->>'timer_end' is not null then return snap; end if;
      g := g || jsonb_build_object('timer_end',stamp + make_interval(secs=>(g->>'seconds')::integer));
    elsif p_action='pin' then
      current_card := g->'current';
      if current_card is null or current_card='null'::jsonb then raise exception 'Draw a card first.'; end if;
      select coalesce(jsonb_agg(v),'[]'::jsonb) into effects from jsonb_array_elements(coalesce(g->'rules','[]'::jsonb)) v where v->>'instance'<>current_card->>'instance';
      if jsonb_array_length(effects)>=50 then raise exception 'Clear a saved card first.'; end if;
      g := g || jsonb_build_object('rules',effects || jsonb_build_array(current_card || '{"expires":null}'::jsonb));
    elsif p_action='dismiss' then
      select coalesce(jsonb_agg(v),'[]'::jsonb) into effects from jsonb_array_elements(coalesce(g->'rules','[]'::jsonb)) v where v->>'instance' is distinct from p_data->>'instance';
      g := g || jsonb_build_object('rules',effects);
    elsif p_action='clear' then
      g := g || '{"rules":[]}'::jsonb;
    else raise exception 'Unknown game action.';
    end if;
  end if;
  if p_action in ('start','next','skip') then
    turn_no := (g->>'round')::integer+1; deck := g->'deck'; roster := g->'players'; total := jsonb_array_length(roster);
    select coalesce(jsonb_agg(v),'[]'::jsonb) into effects from jsonb_array_elements(g->'rules') v
      where (v->>'expires' is null or (v->>'expires')::integer>turn_no)
        and (p_action<>'skip' or v->>'instance' is distinct from g->'current'->>'instance');
    if g->'current' is not null and g->'current'<>'null'::jsonb then
      g := jsonb_set(g,'{history}',coalesce(g->'history','[]'::jsonb) || jsonb_build_array(g->'current'));
    end if;
    if turn_no>jsonb_array_length(deck) then
      g := g || jsonb_build_object('finished',true,'current',null,'timer_end',null,'rules',effects);
    else
      card := deck->(turn_no-1); idx := (turn_no-1)%total; who := roster->idx;
      select jsonb_agg(v order by random()) into others from jsonb_array_elements(roster) with ordinality x(v,n) where n<>idx+1;
      duration := (g->>'turns')::integer; seconds := (g->>'seconds')::integer;
      names := jsonb_build_object('%SELF%',who->>'name','%PLAYER1%',others->0->>'name','%PLAYER2%',others->1->>'name',
        '%PREVIOUS_PLAYER%',roster->((idx+total-1)%total)->>'name','%NEXT_PLAYER%',roster->((idx+1)%total)->>'name',
        '%TURNS%',duration::text || case when position('%TURNS% turns' in card->>'text')>0 then '' else ' turns' end,'%TIME_LIMIT%',seconds::text || ' seconds');
      txt := card->>'text';
      for key,value in select * from jsonb_each_text(names) loop txt := replace(txt,key,coalesce(value,'')); end loop;
      current_card := (card-'text') || jsonb_build_object('text',txt,'player',who->>'name','instance',turn_no::text,'timed',position('%TIME_LIMIT%' in card->>'text')>0);
      if position('%TURNS%' in card->>'text')>0 then
        effects := effects || jsonb_build_array(current_card || jsonb_build_object('expires',turn_no+duration));
      end if;
      if card->>'title'='Circle of Silencing' then effects := '[]'::jsonb; end if;
      g := g || jsonb_build_object('round',turn_no,'current',current_card,'rules',effects,'timer_end',null,'finished',false);
    end if;
  end if;
  g := g || jsonb_build_object('revision',next_rev);
  update public.reparty_rooms set settings=settings || jsonb_build_object('game',g),playback=pb,revision=revision+1,updated_at=stamp where id=p_room;
  return public.reparty_action('snapshot',p_room,'{}'::jsonb);
end;
$game$;
revoke all on function reparty_private.game_action(text,text,jsonb) from public, anon;
grant execute on function reparty_private.game_action(text,text,jsonb) to authenticated;
create or replace function public.reparty_game_action(p_action text, p_room text, p_data jsonb default '{}'::jsonb)
returns jsonb language sql security invoker set search_path = '' as $api$
  select reparty_private.game_action(p_action,p_room,p_data);
$api$;
revoke all on function public.reparty_game_action(text,text,jsonb) from public, anon;
grant execute on function public.reparty_game_action(text,text,jsonb) to authenticated;

commit;
